export async function uploadOrganizationLogo(organizationId:string,file:File,previousPath?:string|null){const allowed=['image/png','image/jpeg','image/webp'];if(!allowed.includes(file.type))throw new AppError('Use a PNG, JPG, or WebP logo.','invalid_logo_type');if(file.size>2*1024*1024)throw new AppError('Logo files are limited to 2 MB.','logo_too_large');const extension=file.type==='image/png'?'png':file.type==='image/webp'?'webp':'jpg';const storagePath=`${organizationId}/logo-${crypto.randomUUID()}.${extension}`;const upload=await supabase.storage.from('organization-assets').upload(storagePath,file,{contentType:file.type,upsert:false,cacheControl:'3600'});if(upload.error)fail(upload.error,'Could not upload organization logo');const {error}=await supabase.from('organization_settings').update({logo_path:storagePath,updated_at:new Date().toISOString()}).eq('organization_id',organizationId);if(error){await supabase.storage.from('organization-assets').remove([storagePath]);fail(error,'Could not save organization logo')}if(previousPath&&previousPath!==storagePath)await supabase.storage.from('organization-assets').remove([previousPath]);return storagePath}
/* The mandatory client profile template prints a banner across the footer of every page. It is a
 * distinct asset from the navigation logo -- different artwork, different aspect ratio -- but it is
 * stored inside the settings blob rather than its own column, so it needs no schema change. Both
 * writes read-modify-write that blob; there is one settings row per organization and only an owner
 * can reach this screen, so the race is not worth an RPC. */
async function patchOrganizationSettings(organizationId:string,change:Record<string,unknown>){
  const current=await supabase.from('organization_settings').select('settings').eq('organization_id',organizationId).maybeSingle()
  if(current.error)fail(current.error,'Could not read organization settings')
  const merged={...(current.data?.settings as Record<string,unknown>||{}),...change}
  const {error}=await supabase.from('organization_settings').update({settings:merged as unknown as Json,updated_at:new Date().toISOString()}).eq('organization_id',organizationId)
  if(error)fail(error,'Could not save organization settings')
}

/* Both were hardcoded in the candidate page: a 62 country code and an English opening line, in a
 * product sold to agencies that are not all Indonesian and do not all write to candidates in English.
 * Validated here rather than only in the form, because this blob is also the thing a future import or
 * script would write to. */
export async function updateWhatsAppSettings(organizationId:string,input:{countryCode:string;template:string}){
  const code=input.countryCode.replace(/\D/g,'')
  if(!/^\d{1,4}$/.test(code))throw new AppError('Country code must be 1–4 digits, without a plus sign.','invalid_country_code')
  await patchOrganizationSettings(organizationId,{whatsapp_country_code:code,whatsapp_template:input.template.trim()||null})
}
export async function uploadOrganizationProfileBanner(organizationId:string,file:File,previousPath?:string|null){const allowed=['image/png','image/jpeg','image/webp'];if(!allowed.includes(file.type))throw new AppError('Use a PNG, JPG, or WebP banner.','invalid_banner_type');if(file.size>2*1024*1024)throw new AppError('Banner files are limited to 2 MB.','banner_too_large');const extension=file.type==='image/png'?'png':file.type==='image/webp'?'webp':'jpg';const storagePath=`${organizationId}/profile-banner-${crypto.randomUUID()}.${extension}`;const upload=await supabase.storage.from('organization-assets').upload(storagePath,file,{contentType:file.type,upsert:false,cacheControl:'3600'});if(upload.error)fail(upload.error,'Could not upload profile banner');try{await patchOrganizationSettings(organizationId,{profile_footer_banner_path:storagePath})}catch(error){await supabase.storage.from('organization-assets').remove([storagePath]);throw error}if(previousPath&&previousPath!==storagePath)await supabase.storage.from('organization-assets').remove([previousPath]);return storagePath}
export async function removeOrganizationProfileBanner(organizationId:string,bannerPath:string){await patchOrganizationSettings(organizationId,{profile_footer_banner_path:null});const removed=await supabase.storage.from('organization-assets').remove([bannerPath]);if(removed.error)fail(removed.error,'Banner setting was cleared, but the old file could not be removed')}

export async function removeOrganizationLogo(organizationId:string,logoPath:string){const {error}=await supabase.from('organization_settings').update({logo_path:null,updated_at:new Date().toISOString()}).eq('organization_id',organizationId);if(error)fail(error,'Could not remove organization logo');const removed=await supabase.storage.from('organization-assets').remove([logoPath]);if(removed.error)fail(removed.error,'Logo setting was cleared, but the old file could not be removed')}

