export async function listCandidateDocuments(organizationId:string,candidateId:string){const {data,error}=await supabase.from('document_links').select('documents!inner(id,file_name,original_filename,mime_type,storage_path,size_bytes,document_type,created_at,deleted_at)').eq('organization_id',organizationId).eq('candidate_id',candidateId);if(error)fail(error,'Could not load documents');const validated=rows(data,documentLinkRowSchema,'Document link rows did not match the expected shape');const documents=validated.flatMap((item)=>{const value=item.documents as CandidateDocument|CandidateDocument[];return Array.isArray(value)?value:[value]}).filter((document)=>document&&!('deleted_at' in document&&document.deleted_at));return Promise.all(documents.map(async(document)=>{const {data:signed}=await supabase.storage.from('candidate-documents').createSignedUrl(document.storage_path,300);return {...document,signedUrl:signed?.signedUrl}}))}
export async function uploadCandidateDocument(organizationId:string,candidateId:string,userId:string,file:File){if(file.size>25*1024*1024)throw new AppError('Documents are limited to 25 MB.','file_too_large');const safeName=file.name.replace(/[^a-zA-Z0-9._-]+/g,'-');const storagePath=`${organizationId}/${candidateId}/${crypto.randomUUID()}-${safeName}`;const upload=await supabase.storage.from('candidate-documents').upload(storagePath,file,{contentType:file.type||'application/octet-stream',upsert:false});if(upload.error)fail(upload.error,'Could not upload document');const {data:document,error}=await supabase.from('documents').insert({organization_id:organizationId,file_name:safeName,original_filename:file.name,storage_path:storagePath,mime_type:file.type||'application/octet-stream',size_bytes:file.size,document_type:'resume',uploaded_by:userId}).select('id').single();if(error){await supabase.storage.from('candidate-documents').remove([storagePath]);fail(error,'Could not register document')}const link=await supabase.from('document_links').insert({organization_id:organizationId,document_id:document.id,candidate_id:candidateId});if(link.error){await Promise.all([supabase.from('documents').delete().eq('id',document.id),supabase.storage.from('candidate-documents').remove([storagePath])]);fail(link.error,'Could not link document')}return document.id as string}
export async function uploadCandidateProfileDocument(organizationId:string,candidateId:string,userId:string,file:File){const allowed=['application/vnd.openxmlformats-officedocument.wordprocessingml.document'];if(!allowed.includes(file.type))throw new AppError('Candidate profiles must be DOCX.','invalid_profile_document');const safeName=file.name.replace(/[^a-zA-Z0-9._-]+/g,'-');const storagePath=`${organizationId}/${candidateId}/profiles/${crypto.randomUUID()}-${safeName}`;const upload=await supabase.storage.from('candidate-documents').upload(storagePath,file,{contentType:file.type,upsert:false});if(upload.error)fail(upload.error,'Could not upload generated profile');const {data:document,error}=await supabase.from('documents').insert({organization_id:organizationId,file_name:safeName,original_filename:file.name,storage_path:storagePath,mime_type:file.type,size_bytes:file.size,document_type:'candidate_profile',uploaded_by:userId}).select('id').single();if(error){await supabase.storage.from('candidate-documents').remove([storagePath]);fail(error,'Could not register generated profile')}const link=await supabase.from('document_links').insert({organization_id:organizationId,document_id:document.id,candidate_id:candidateId});if(link.error){await Promise.all([supabase.from('documents').delete().eq('id',document.id),supabase.storage.from('candidate-documents').remove([storagePath])]);fail(link.error,'Could not link generated profile')}return {id:document.id as string,storagePath}}
