const pdfMime='application/pdf';const docxMime='application/vnd.openxmlformats-officedocument.wordprocessingml.document'
function cvMime(file:File){if(file.type===pdfMime||file.type===docxMime)return file.type;const name=file.name.toLowerCase();if(name.endsWith('.pdf'))return pdfMime;if(name.endsWith('.docx'))return docxMime;throw new AppError('Upload a PDF or DOCX CV.','unsupported_cv_type')}
export async function startCandidateCvParse(organizationId:string,userId:string,file:File,targetCandidateId?:string|null){const mimeType=cvMime(file);const max=mimeType===docxMime?10*1024*1024:25*1024*1024;if(file.size<1||file.size>max)throw new AppError(mimeType===docxMime?'DOCX CVs are limited to 10 MB.':'PDF CVs are limited to 25 MB.','cv_too_large');const parseId=crypto.randomUUID();const safeName=file.name.replace(/[^a-zA-Z0-9._-]+/g,'-');const storagePath=`${organizationId}/cv-drafts/${userId}/${parseId}/${safeName}`;const upload=await supabase.storage.from('candidate-documents').upload(storagePath,file,{contentType:mimeType,upsert:false});if(upload.error)fail(upload.error,'Could not upload CV');try{await invoke<{parseId:string}>('parse-candidate-cv',{action:'start',organizationId,parseId,storagePath,originalFilename:file.name,mimeType,targetCandidateId:targetCandidateId||null});return parseId}catch(error){await supabase.storage.from('candidate-documents').remove([storagePath]);throw error}}
export async function getCandidateCvParse(organizationId:string,parseId:string){const result=await invoke<CvParseResult>('parse-candidate-cv',{action:'status',organizationId,parseId});if(result.extraction)result.extraction=candidateCvExtractionSchema.parse(result.extraction);return result}
