export async function acceptCandidateCvParse(organizationId:string,parseId:string,extraction:CandidateCvExtraction,targetCandidateId?:string|null){const payload=candidateCvExtractionSchema.parse(extraction);const {data,error}=await supabase.rpc('accept_candidate_cv_parse',{p_organization_id:organizationId,p_parse_id:parseId,p_payload:payload as unknown as Json,p_target_candidate_id:targetCandidateId||undefined});if(error)fail(error,error.message.includes('duplicate_candidate')?'A candidate with this email already exists.':'Could not save the parsed CV');return data as string}
export async function listCandidateJobs(organizationId:string,candidateId:string):Promise<CandidateProfileJob[]>{const {data,error}=await supabase.from('job_candidates').select('jobs!inner(id,title,deleted_at,companies(name))').eq('organization_id',organizationId).eq('candidate_id',candidateId);if(error)fail(error,'Could not load linked vacancies');const validated=rows(data,candidateJobLinkRowSchema,'Candidate job link rows did not match the expected shape');return validated.map((item)=>item.jobs).filter((job)=>job&&!job.deleted_at).map((job)=>({id:job.id,title:job.title,company_name:job.companies?.name||null}))}
export async function hasOrganizationPermission(organizationId:string,permission:string){const {data,error}=await supabase.rpc('has_permission',{p_organization_id:organizationId,p_permission:permission});if(error)fail(error,'Could not check workspace permissions');return Boolean(data)}
/* Replaces the 15-parallel-has_permission fan-out that used to back useWorkspaceCapabilities. The
 * RPC always returns exactly one row -- an all-false row for a non-member -- so the empty fallback
 * here is for a genuinely unreachable response shape, not for the ordinary "no access" case. */
export async function getWorkspaceCapabilities(organizationId:string):Promise<WorkspaceCapabilities>{
  const {data,error}=await supabase.rpc('get_my_workspace_capabilities',{p_organization_id:organizationId})
  if(error)fail(error,'Could not load workspace permissions')
  const capabilities=data?.[0]
  if(!capabilities)return {roleKeys:[],canWriteCandidates:false,canWriteClients:false,canWriteJobs:false,canMovePipeline:false,canSubmit:false,canManageInterviews:false,canManageOffers:false,canManagePlacements:false,canManageCommercialTerms:false,canViewTeamReports:false,canManageFinance:false,canImport:false,canManageOrganization:false,canManageWorkspace:false,canManageTemplates:false,canViewAdmin:false,readOnly:true}
  return {
    roleKeys:capabilities.role_keys||[],
    canWriteCandidates:capabilities.can_write_candidates,canWriteClients:capabilities.can_write_clients,canWriteJobs:capabilities.can_write_jobs,
    canMovePipeline:capabilities.can_move_pipeline,canSubmit:capabilities.can_submit,canManageInterviews:capabilities.can_manage_interviews,
    canManageOffers:capabilities.can_manage_offers,canManagePlacements:capabilities.can_manage_placements,canManageCommercialTerms:capabilities.can_manage_commercial_terms,
    canViewTeamReports:capabilities.can_view_team_reports,canManageFinance:capabilities.can_manage_finance,canImport:capabilities.can_import,
    canManageOrganization:capabilities.can_manage_organization,canManageWorkspace:capabilities.can_manage_workspace,canManageTemplates:capabilities.can_manage_templates,
    canViewAdmin:capabilities.can_view_admin,readOnly:capabilities.read_only,
  }
}
export async function listCandidateProfileTemplates(organizationId:string):Promise<CandidateProfileTemplate[]>{const {data,error}=await supabase.from('templates').select('id,name,configuration,version,is_default,created_at,updated_at').eq('organization_id',organizationId).eq('template_type','candidate_profile').is('deleted_at',null).order('is_default',{ascending:false}).order('name');if(error)fail(error,'Could not load candidate profile templates');return (data||[]).map((item)=>({...item,configuration:candidateProfileTemplateConfigSchema.parse(item.configuration)}))}
// The generated type requires p_template_id:string, but the RPC's own SQL (create_candidate_profile
// template) declares it as a bare `uuid` with no default and explicitly branches on `is null` to tell
// insert from update -- Postgres function parameters have no NOT NULL syntax at all, so this is
// genuinely nullable at the database level; the type generator just doesn't infer that for a
// no-default parameter. `null` here is required, not a workaround -- it's what tells the RPC to
// create a new template rather than update an existing one.
export async function saveCandidateProfileTemplate(organizationId:string,input:{id?:string;name:string;configuration:unknown;isDefault:boolean}){const configuration=candidateProfileTemplateConfigSchema.parse(input.configuration);const {data,error}=await supabase.rpc('save_candidate_profile_template',{p_organization_id:organizationId,p_template_id:(input.id||null) as string,p_name:input.name,p_configuration:configuration as unknown as Json,p_is_default:input.isDefault});if(error)fail(error,'Could not save candidate profile template');return data as string}
export async function archiveCandidateProfileTemplate(organizationId:string,templateId:string){const {error}=await supabase.rpc('archive_candidate_profile_template',{p_organization_id:organizationId,p_template_id:templateId});if(error)fail(error,error.message.includes('last_template_required')?'Keep at least one candidate profile template.':'Could not archive candidate profile template')}
export async function generateCandidateProfile(input:{organizationId:string;candidateId:string;jobId:string;templateId:string;anonymize:boolean}):Promise<CandidateProfileGeneration>{const result=await invoke<CandidateProfileGeneration>('generate-candidate-profile',input);return {...result,draft:candidateProfileDraftSchema.parse(result.draft),evaluation:{...result.evaluation,evidence:candidateProfileDraftSchema.shape.requirement_evidence.parse(result.evaluation.evidence)}}}
export async function listCandidateProfileVersions(organizationId:string,candidateId:string):Promise<CandidateProfileVersion[]>{const {data,error}=await supabase.from('candidate_profile_versions').select('id,version,status,candidate_id,job_id,template_id,template_version,generated_content,reviewed_content,input_versions,anonymized,docx_document_id,pdf_document_id,created_at,finalized_at,jobs(title,updated_at),templates(name,version),candidates!candidate_id(updated_at)').eq('organization_id',organizationId).eq('candidate_id',candidateId).order('created_at',{ascending:false});if(error)fail(error,'Could not load candidate profile versions');const validated=rows(data,candidateProfileVersionRowSchema,'Candidate profile version rows did not match the expected shape');return validated.map((item)=>{const {jobs:job,templates:template,candidates:candidate,input_versions:inputVersions,...rest}=item;return {...rest,generated_content:candidateProfileDraftSchema.parse(item.generated_content),reviewed_content:item.reviewed_content?candidateProfileDraftSchema.parse(item.reviewed_content):null,input_versions:inputVersions,job_title:job.title,template_name:template.name,stale:hasStaleProfileInputs(inputVersions,{candidateUpdatedAt:candidate.updated_at,jobUpdatedAt:job.updated_at,templateVersion:template.version})}}) as CandidateProfileVersion[]}
/* DOCX is the only client-facing output; the mandatory client template is a Word file consultants
 * still complete by hand. p_pdf_document_id is retained on the RPC for signature stability and is
 * ignored, so it is always passed null. */
export async function finalizeCandidateProfile(input:{organizationId:string;profileVersionId:string;reviewedContent:unknown;anonymized:boolean;docxDocumentId:string;editedFieldCount:number}){const reviewed=candidateProfileDraftSchema.parse(input.reviewedContent);
  // Same class of gap as p_fee_percentage/p_fixed_fee below: supabase gen types infers a no-default
  // plpgsql parameter as its bare declared type (string), not string | null, because it has no way to
  // introspect a function parameter's true nullability the way it can a column's NOT NULL. Passing
  // null here is correct -- see the type's own comment -- the generated signature is just incomplete.
  const {data,error}=await supabase.rpc('finalize_candidate_profile',{p_organization_id:input.organizationId,p_profile_version_id:input.profileVersionId,p_reviewed_content:reviewed as unknown as Json,p_anonymized:input.anonymized,p_docx_document_id:input.docxDocumentId,p_pdf_document_id:null as unknown as string,p_edited_field_count:input.editedFieldCount});if(error)fail(error,'Could not finalize candidate profile');return data as string}
export async function recordCandidateProfileExportFailure(organizationId:string,profileVersionId:string,reason:string){const {error}=await supabase.rpc('record_candidate_profile_export_failure',{p_organization_id:organizationId,p_profile_version_id:profileVersionId,p_reason:reason.slice(0,500)});if(error)console.error('Could not record candidate profile export failure',error)}
// started_on_precision/ended_on_precision are optional so the plain one-field-at-a-time add form
// (which never captured precision) keeps its old "day if a date was entered" default, while callers
// that do collect a precision (the shared list editors) can pass the consultant's actual choice
// through instead of it being silently downgraded to 'day'.
export async function addCandidateEmployment(organizationId:string,candidateId:string,values:{company_name:string;title:string;location?:string|null;started_on?:string|null;ended_on?:string|null;is_current:boolean;summary?:string|null;started_on_precision?:string|null;ended_on_precision?:string|null}){const {error}=await supabase.from('candidate_employment').insert({organization_id:organizationId,candidate_id:candidateId,company_name:values.company_name,title:values.title,location:values.location||null,is_current:values.is_current,started_on:values.started_on||null,ended_on:values.ended_on||null,started_on_precision:values.started_on_precision??(values.started_on?'day':null),ended_on_precision:values.ended_on_precision??(values.ended_on?'day':null),summary:values.summary||null});if(error)fail(error,'Could not add employment')}
export async function addCandidateEducation(organizationId:string,candidateId:string,values:{institution:string;degree?:string|null;field_of_study?:string|null;started_on?:string|null;ended_on?:string|null;started_on_precision?:string|null;ended_on_precision?:string|null}){const {error}=await supabase.from('candidate_education').insert({organization_id:organizationId,candidate_id:candidateId,institution:values.institution,degree:values.degree||null,field_of_study:values.field_of_study||null,started_on:values.started_on||null,ended_on:values.ended_on||null,started_on_precision:values.started_on_precision??(values.started_on?'day':null),ended_on_precision:values.ended_on_precision??(values.ended_on?'day':null)});if(error)fail(error,'Could not add education')}
export async function addCandidateLanguage(organizationId:string,candidateId:string,language:string,proficiency:string){const {error}=await supabase.from('candidate_languages').insert({organization_id:organizationId,candidate_id:candidateId,language:language.trim(),proficiency:proficiency.trim()||null});if(error)fail(error,'Could not add language')}
// Shared by add and update: skills are resolved through the org's `skills` table by
// normalized_name, so renaming a skill on a candidate means finding-or-creating the *target*
// skill_id, not editing the name in place.
async function resolveSkillId(organizationId:string,name:string){const normalized=name.trim().toLowerCase().replace(/\s+/g,' ');const existing=await supabase.from('skills').select('id').eq('organization_id',organizationId).eq('normalized_name',normalized).maybeSingle();if(existing.error)fail(existing.error,'Could not find skill');if(existing.data)return existing.data.id as string;const created=await supabase.from('skills').insert({organization_id:organizationId,name:name.trim(),normalized_name:normalized}).select('id').single();if(created.error)fail(created.error,'Could not create skill');return created.data.id as string}
export async function addCandidateSkill(organizationId:string,candidateId:string,name:string,proficiency:string,yearsExperience?:number){const skillId=await resolveSkillId(organizationId,name);const {error}=await supabase.from('candidate_skills').upsert({organization_id:organizationId,candidate_id:candidateId,skill_id:skillId,proficiency:proficiency.trim()||null,years_experience:yearsExperience??null});if(error)fail(error,'Could not add skill')}
export async function addCandidateTag(organizationId:string,candidateId:string,name:string){const normalized=name.trim();let tagId:string;const existing=await supabase.from('tags').select('id').eq('organization_id',organizationId).ilike('name',normalized).maybeSingle();if(existing.error)fail(existing.error,'Could not find tag');if(existing.data)tagId=existing.data.id;else{const created=await supabase.from('tags').insert({organization_id:organizationId,name:normalized}).select('id').single();if(created.error)fail(created.error,'Could not create tag');tagId=created.data.id}const {error}=await supabase.from('candidate_tags').upsert({organization_id:organizationId,candidate_id:candidateId,tag_id:tagId});if(error)fail(error,'Could not add tag')}
export async function removeCandidateSkill(organizationId:string,candidateId:string,skillId:string){const {error}=await supabase.from('candidate_skills').delete().eq('organization_id',organizationId).eq('candidate_id',candidateId).eq('skill_id',skillId);if(error)fail(error,'Could not remove skill')}
export async function removeCandidateTag(organizationId:string,candidateId:string,tagId:string){const {error}=await supabase.from('candidate_tags').delete().eq('organization_id',organizationId).eq('candidate_id',candidateId).eq('tag_id',tagId);if(error)fail(error,'Could not remove tag')}
