// The four functions below back Phase 5's in-place panel editing on the candidate detail page --
// they replace the "add one entry at a time, never edit an existing one" flow that AddProfileItem
// used to be the only way to touch these tables.
export async function updateCandidateEmployment(organizationId:string,id:string,values:{company_name:string;title:string;location?:string|null;started_on?:string|null;ended_on?:string|null;is_current:boolean;summary?:string|null;started_on_precision?:string|null;ended_on_precision?:string|null}){const {error}=await supabase.from('candidate_employment').update({company_name:values.company_name,title:values.title,location:values.location||null,is_current:values.is_current,started_on:values.started_on||null,ended_on:values.ended_on||null,started_on_precision:values.started_on_precision??(values.started_on?'day':null),ended_on_precision:values.ended_on_precision??(values.ended_on?'day':null),summary:values.summary||null}).eq('organization_id',organizationId).eq('id',id);if(error)fail(error,'Could not update employment')}
