export async function setCompanyDefaultFee(organizationId:string,companyId:string,input:{feeType:'percentage'|'fixed'|'retained';feePercentage?:number;fixedFee?:number;currency:string;guaranteeDays:number;paymentTermsDays?:number;taxTreatment?:string;replacementTerms?:string;agreementDocumentUrl?:string;approvalStatus?:'draft'|'pending_approval'|'approved'|'rejected';notes?:string}){const {data,error}=await supabase.rpc('set_company_default_fee',{p_organization_id:organizationId,p_company_id:companyId,p_fee_type:input.feeType,// The generated type marks these `number`, not `number | null`: supabase gen types has no way to
      // introspect nullability of a plpgsql parameter (unlike a table column's NOT NULL), so it falls back
      // to the bare declared type. The function body itself branches on `is null` for whichever of the two
      // doesn't apply to the chosen fee_type, so passing null here is the correct runtime call.
      p_fee_percentage:(input.feePercentage??null) as number,p_fixed_fee:(input.fixedFee??null) as number,p_currency:input.currency,p_guarantee_days:input.guaranteeDays,p_payment_terms_days:input.paymentTermsDays??undefined,p_tax_treatment:input.taxTreatment||undefined,p_replacement_terms:input.replacementTerms||undefined,p_agreement_document_url:input.agreementDocumentUrl||undefined,p_approval_status:input.approvalStatus||'approved',p_notes:input.notes||undefined});if(error)fail(error,'Could not save account fee defaults');return data as string}
