export async function listSavedViews(organizationId:string,resource:SavedViewResource){const {data,error}=await supabase.from('saved_views').select('id,organization_id,owner_member_id,resource,name,filters,columns,is_shared,is_default,updated_at').eq('organization_id',organizationId).eq('resource',resource).order('name');if(error)fail(error,'Could not load saved views');return rows(data,savedViewSchema,'Saved view rows did not match the expected shape') as SavedView[]}
export async function saveView(organizationId:string,memberId:string,resource:SavedViewResource,input:{id?:string;name:string;filters:Record<string,unknown>;columns:string[];isShared:boolean;isDefault:boolean}){
  const row={organization_id:organizationId,owner_member_id:memberId,resource,name:input.name.trim(),filters:input.filters as Json,columns:input.columns as unknown as Json,is_shared:input.isShared,is_default:input.isDefault,updated_at:new Date().toISOString()}
  // A member may only hold one default per resource, so promoting one demotes the rest first. Doing
  // this before the write means a failed write cannot leave the member with no default at all.
  if(input.isDefault){const {error}=await supabase.from('saved_views').update({is_default:false}).eq('organization_id',organizationId).eq('owner_member_id',memberId).eq('resource',resource);if(error)fail(error,'Could not update the default view')}
  const result=input.id
    ?await supabase.from('saved_views').update(row).eq('id',input.id).select('id').single()
    :await supabase.from('saved_views').insert(row).select('id').single()
  if(result.error)fail(result.error,result.error.code==='23505'?'You already have a view with that name.':'Could not save this view')
  return result.data.id as string
}
export async function deleteSavedView(id:string){const {error}=await supabase.from('saved_views').delete().eq('id',id);if(error)fail(error,'Could not delete this view')}

