export async function getAgencyPerformance(organizationId:string,from:string,to:string){
  const [jobs,activeJobs,packages,interviews,offers,placements,tasks]=await Promise.all([
    supabase.from('jobs').select('id,status,owner_member_id').eq('organization_id',organizationId).gte('created_at',from).lte('created_at',to),
    supabase.from('jobs').select('id,status,owner_member_id').eq('organization_id',organizationId).eq('status','open').is('deleted_at',null),
    supabase.from('submission_packages').select('id,created_by,candidate_submissions(id,job_candidate_id)').eq('organization_id',organizationId).gte('created_at',from).lte('created_at',to),
    supabase.from('interviews').select('id,job_candidate_id,created_by,status').eq('organization_id',organizationId).gte('created_at',from).lte('created_at',to),
    supabase.from('offers').select('id,job_candidate_id,created_by,status').eq('organization_id',organizationId).gte('created_at',from).lte('created_at',to),
    supabase.from('placements').select('id,job_candidate_id,created_by,placement_fee,currency,status').eq('organization_id',organizationId).gte('created_at',from).lte('created_at',to),
    supabase.from('tasks').select('id,owner_member_id,status,due_at,deleted_at').eq('organization_id',organizationId).is('deleted_at',null),
  ])
  for(const result of [jobs,activeJobs,packages,interviews,offers,placements,tasks])if(result.error)fail(result.error,'Could not load agency performance')
  const submissions=(packages.data||[]).flatMap((pack)=>(pack.candidate_submissions||[]).map((submission)=>({...submission,created_by:pack.created_by})))
  return {jobs:jobs.data||[],activeJobs:activeJobs.data||[],submissions,interviews:interviews.data||[],offers:offers.data||[],placements:placements.data||[],tasks:tasks.data||[]}
}

export async function createRevenueSplit(organizationId:string,placementId:string,memberId:string,percentage:number){const {error}=await supabase.rpc('create_placement_revenue_split',{p_organization_id:organizationId,p_placement_id:placementId,p_member_id:memberId,p_percentage:percentage});if(error)fail(error,error.message.includes('split_total_exceeds_100')?'Consultant credits cannot exceed 100%.':'Could not create revenue split')}
export async function createInvoice(organizationId:string,placementId:string,invoiceNumber:string,amount:number,currency:string,dueDate:string){const {error}=await supabase.from('placement_invoices').insert({organization_id:organizationId,placement_id:placementId,invoice_reference:invoiceNumber,amount,currency,due_on:dueDate,status:'draft'});if(error)fail(error,'Could not create invoice')}
export async function updateInvoiceStatus(organizationId:string,invoiceId:string,status:'issued'|'paid'|'void'){const values=status==='issued'?{status,issued_on:new Date().toISOString().slice(0,10)}:status==='paid'?{status,paid_on:new Date().toISOString().slice(0,10)}:{status};const {error}=await supabase.from('placement_invoices').update(values).eq('organization_id',organizationId).eq('id',invoiceId);if(error)fail(error,'Could not update invoice')}
